const raw = $input.first().json;
const input = raw.body || raw;
const headers = raw.headers || {};

let chat_id, message_id, question, channel;

if (input.message) {
  // Пришло из Telegram
  chat_id = input.message.chat.id;
  message_id = input.message.message_id;
  question = input.message.text;
  channel = 'telegram';
} else {
  // Пришло с сайта: { question, chat_id }
  chat_id = input.chat_id;
  question = input.question;
  message_id = chat_id + '_' + Date.now();
  channel = 'web';
}

// IP пользователя (заголовок прокси) — нужен для лимита вопросов по адресу
const user_ip = String(headers['x-forwarded-for'] || headers['x-real-ip'] || '')
  .split(',')[0].trim();

if (!question) {
  throw new Error('Пустое сообщение');
}

return [{ json: { chat_id, message_id, question, channel, user_ip } }];

const staticData = $getWorkflowStaticData('global');
if (!staticData.processed) staticData.processed = {};

// Проверяем, есть ли message_id
if (!$json.message_id) {
  // Если нет — пропускаем идемпотентность (или логируем ошибку)
  return [{ json: { ...$json, already_processed: false } }];
}

const key = String($json.message_id);
const alreadyProcessed = !!staticData.processed[key];

return [{ json: { ...$json, already_processed: alreadyProcessed } }];

const SYSTEM_PROMPT = `# Роль
Ты — Нямыч, внутренний помощник сети ресторанов «Вкусный Дом».
Ты как опытный коллега, к которому все идут за советом — спокойный,
свойский, всегда готов помочь, без формальной "казёнщины".

# Задача
Отвечай сотрудникам на вопросы о правилах, процедурах, графиках,
стандартах сервиса и рабочих регламентах компании — опираясь
исключительно на базу знаний.

# Правила
- Обращайся к сотруднику всегда на «Вы» (с большой буквы) — вежливо, но без канцелярской сухости. Никогда не переходи на «ты», даже если сотрудник сам пишет неформально.
- Отвечай кратко, по делу, дружелюбным тоном — как человек с опытом,
  а не инструкция.
- Всегда указывай источник информации (документ и, если есть,
  статью закона).
- Если вопрос касается изменений в законодательстве — упоминай дату
  актуализации документа и советуй уточнить у HR при малейшем сомнении.
- Если не знаешь ответа или информации нет в базе знаний — скажи честно
  и направь к HR-менеджеру. Никогда не придумывай ответ.
- Сложные, спорные или персональные случаи (индивидуальные трудовые
  споры, вопросы про чью-то конкретную зарплату) — сразу передавай HR.
- Не давай юридических консультаций за рамками внутренних регламентов
  компании.

# Формат ответа
Короткий абзац или список из 2-4 пунктов. Без длинных вступлений.
В конце — ссылка на документ-источник в формате: (Источник: название_документа.md)`;

// Берём вопрос и chat_id НЕ из текущего $json (там уже данные Qdrant,
// а не исходное сообщение), а напрямую из более раннего узла —
// того же принципа, что уже применён в OUT_Telegram_Reply.
const originalData = $('CORE_Validate_Input').item.json;
const question = originalData.question || 'Вопрос не указан';
const chat_id = originalData.chat_id;

// Результаты поиска Qdrant — они сейчас как раз в $input
const results = $input.all();

let context = '';
if (Array.isArray(results) && results.length > 0) {
  context = results
    .map(r => {
      const text = r.json?.document?.pageContent || '';
      const source = r.json?.document?.metadata?.source
                  || r.json?.document?.metadata?.file_name || '';
      if (!text) return '';
      return source ? `[${source}]:\n${text}` : text;
    })
    .filter(Boolean)
    .join('\n\n---\n\n');
}

const final_prompt = `${SYSTEM_PROMPT}

Контекст из базы знаний:
${context || 'В базе знаний не нашлось релевантной информации по этому вопросу.'}

Вопрос сотрудника: ${question}`;

const escaped_prompt = JSON.stringify(final_prompt).slice(1, -1);
// Экранируем вопрос тем же приёмом, что final_prompt: иначе сырой перенос/кавычка
// в вопросе ломает JSON-тело запроса к OpenAI (Bad control character in string literal).
const escaped_question = JSON.stringify(question).slice(1, -1);

return [{
  json: {
    chat_id,
    question,
    final_prompt: escaped_prompt,
    question_escaped: escaped_question
  }
}];

const staticData = $getWorkflowStaticData('global');

// Берём данные из входящего сообщения
const chat_id = $json.chat_id || $input.first().json.chat_id;
const question = $json.question || $input.first().json.question;
const message_id = $json.message_id || $input.first().json.message_id;
const answer_text = $json.answer_text || $input.first().json.answer_text;

// Сохраняем в статическое хранилище
if (message_id) {
  if (!staticData.processed) staticData.processed = {};
  staticData.processed[String(message_id)] = { 
    stage: 'answer_generated', 
    ts: Date.now() 
  };
}

// Возвращаем исходные данные, не меняя их
return [{
  json: {
    chat_id: chat_id,
    question: question,
    message_id: message_id,
    answer_text: answer_text
  }
}];

// Получаем статические данные
const staticData = $getWorkflowStaticData('global');

// Полностью очищаем все сохраненные данные
staticData.processed = {};

// Выводим подтверждение
return [{
  json: {
    success: true,
    message: 'Статическое хранилище очищено',
    data: staticData.processed
  }
}];

const response = $input.first().json;
const body = response.body || response;
const answer = body.choices?.[0]?.message?.content || 'Не удалось получить ответ';

const chat_id = $json.chat_id || $input.first().json.chat_id;
const question = $json.question || $input.first().json.question;
const channel = $json.channel || $input.first().json.channel;

return [{
  json: { chat_id, question, answer_text: answer, channel }
}];

// Лимит: не более 5 вопросов на одного пользователя веб-канала за всё время.
// Счётчик — в статическом хранилище workflow (сброс только через PUT staticData={}).
// Проверка стоит перед вызовом LLM — заблокированный пользователь не тратит токены.
const LIMIT = 7;
const WHITELIST_IPS = [
  '92.124.163.100'  // Медвежка: доверенный IP — лимит не считается
];
const LIMIT_MESSAGE = "Ваш лимит вопросов исчерпан. Обратитесь, пожалуйста, к администратору.";

const staticData = $getWorkflowStaticData('global');
if (!staticData.rateLimits) staticData.rateLimits = {};

const item = $input.first().json;

// Ограничиваем только анонимный веб-канал (Telegram-бот для сотрудников — без лимита)
if (item.channel !== 'web') {
  return [{ json: item }];
}

const ip = String(item.user_ip || '').trim();

// Белый список: доверенные адреса — счётчик не трогаем; rate_left 999
// означает клиенту "без лимита" (счётчик уходит в минус и не срабатывает)
if (ip && WHITELIST_IPS.indexOf(ip) !== -1) {
  return [{ json: { ...item, rate_blocked: false, rate_left: 999 } }];
}

// Ключ пользователя: сначала IP (устойчивее), иначе постоянный chat_id виджета
const key = ip ? 'ip_' + ip : 'cid_' + item.chat_id;

const used = staticData.rateLimits[key] || 0;

if (used >= LIMIT) {
  // Лимит исчерпан — отвечаем мимо LLM и базы знаний
  return [{ json: {
    ...item,
    rate_blocked: true,
    rate_left: 0,
    answer_text: LIMIT_MESSAGE
  } }];
}

staticData.rateLimits[key] = used + 1;

return [{ json: { ...item, rate_blocked: false, rate_left: LIMIT - used - 1 } }];
